INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('global supply chain', '', '', '[{"en":"Disruptions to the global supply chain affect companies worldwide.","zh-TW":"全球供應鏈的中斷影響了全球企業。"},{"en":"Managing a global supply chain requires coordination across time zones.","zh-TW":"管理全球供應鏈需要跨時區協調。"}]', 'phrasal verb'),
('gross revenue', '', '', '[{"en":"Gross revenue reached 100 million for the first time.","zh-TW":"總收入首次達到了1億元。"},{"en":"Gross revenue figures are reported before returns and discounts.","zh-TW":"總收入數字在退貨和折扣前報告。"}]', 'phrasal verb'),
('guarantee period', '', '', '[{"en":"The defect was discovered within the two-year guarantee period.","zh-TW":"在兩年保固期內發現了缺陷。"},{"en":"Customers can claim a replacement within the guarantee period.","zh-TW":"客戶可以在保固期內申請更換。"}]', 'phrasal verb'),
('hard copy', '', '', '[{"en":"Please submit both digital and hard copy versions of the form.","zh-TW":"請提交表格的數位和紙本版本。"},{"en":"The contract must be signed in hard copy for legal validity.","zh-TW":"合約必須以書面形式簽署以具有法律效力。"}]', 'phrasal verb'),
('head of department', '', '', '[{"en":"The head of department approved the new hiring request.","zh-TW":"部門主管批准了新的招聘申請。"},{"en":"She was appointed head of department after 10 years of service.","zh-TW":"她在服務10年後被任命為部門主管。"}]', 'phrasal verb'),
('hedging instrument', '', '', '[{"en":"Interest rate swaps are commonly used as a hedging instrument.","zh-TW":"利率掉期通常被用作對沖工具。"},{"en":"The company selected appropriate hedging instruments for currency risk.","zh-TW":"公司為貨幣風險選擇了適當的對沖工具。"}]', 'phrasal verb'),
('import substitute', '', '', '[{"en":"The government promoted domestic production as import substitutes.","zh-TW":"政府推動國內生產作為進口替代品。"},{"en":"Import substitution reduced dependence on foreign suppliers.","zh-TW":"進口替代降低了對外國供應商的依賴。"}]', 'phrasal verb'),
('incentive bonus', '', '', '[{"en":"Sales staff receive an incentive bonus when they exceed their quota.","zh-TW":"銷售人員超額完成指標時獲得激勵獎金。"},{"en":"The incentive bonus scheme improved team motivation significantly.","zh-TW":"激勵獎金計劃顯著提高了團隊積極性。"}]', 'phrasal verb'),
('income distribution', '', '', '[{"en":"The income distribution policy ensures all tiers receive fair compensation.","zh-TW":"收入分配政策確保所有層級獲得公平報酬。"},{"en":"Widening income distribution creates social and economic challenges.","zh-TW":"擴大的收入分配差距造成了社會和經濟挑戰。"}]', 'phrasal verb'),
('independent review', '', '', '[{"en":"An independent review confirmed the accuracy of the company accounts.","zh-TW":"獨立審查確認了公司帳目的準確性。"},{"en":"The board commissioned an independent review after the allegations.","zh-TW":"董事會在指控後委託了獨立審查。"}]', 'phrasal verb'),
('industry report', '', '', '[{"en":"The industry report predicted 15% growth in cloud computing over 5 years.","zh-TW":"行業報告預測雲端運算在5年內增長15%。"},{"en":"Managers use industry reports to benchmark against peers.","zh-TW":"管理者使用行業報告與同業進行標竿比較。"}]', 'phrasal verb'),
('information disclosure', '', '', '[{"en":"Regulatory frameworks require timely information disclosure by listed firms.","zh-TW":"監管框架要求上市公司及時進行資訊披露。"},{"en":"Information disclosure protects investors from fraud and misrepresentation.","zh-TW":"資訊披露保護投資者免受詐欺和虛假陳述。"}]', 'phrasal verb'),
('infrastructure investment', '', '', '[{"en":"Infrastructure investment improved network reliability across the country.","zh-TW":"基礎設施投資提高了全國網路可靠性。"},{"en":"Government infrastructure investment creates jobs and stimulates growth.","zh-TW":"政府基礎設施投資創造了就業機會並刺激了增長。"}]', 'phrasal verb'),
('integrate operations', '', '', '[{"en":"The company took two years to fully integrate the acquired operations.","zh-TW":"公司花了兩年時間全面整合收購的業務。"},{"en":"Integrating operations eliminated duplication and saved 5 million annually.","zh-TW":"整合業務消除了重複工作，每年節省了500萬元。"}]', 'phrasal verb'),
('internal financing', '', '', '[{"en":"The company relied on internal financing to avoid taking on more debt.","zh-TW":"公司依靠內部融資以避免承擔更多債務。"},{"en":"Internal financing is cheaper but limits the scale of investment.","zh-TW":"內部融資成本更低，但限制了投資規模。"}]', 'phrasal verb'),
('inventory control', '', '', '[{"en":"Automated inventory control reduced stockouts by 30%.","zh-TW":"自動化庫存控制將缺貨次數減少了30%。"},{"en":"Poor inventory control leads to excess stock and tied-up capital.","zh-TW":"糟糕的庫存控制導致過剩庫存和佔用的資本。"}]', 'phrasal verb'),
('joint stock company', '', '', '[{"en":"A joint stock company issues shares to raise capital from investors.","zh-TW":"股份公司通過發行股票向投資者籌集資金。"},{"en":"The largest joint stock companies are listed on stock exchanges.","zh-TW":"最大的股份公司在股票交易所上市。"}]', 'phrasal verb'),
('just cause', '', '', '[{"en":"An employee may be dismissed without notice only if there is just cause.","zh-TW":"只有在有正當理由的情況下，才可在不另行通知的情況下解雇員工。"},{"en":"The company needed to prove just cause before terminating the contract.","zh-TW":"公司需要在終止合約前證明正當理由。"}]', 'phrasal verb'),
('labor productivity', '', '', '[{"en":"Investment in automation doubled labor productivity in three years.","zh-TW":"自動化投資在三年內使勞動生產率翻了一倍。"},{"en":"Labor productivity improvements reduce per-unit manufacturing costs.","zh-TW":"勞動生產率提高降低了製造業的單位成本。"}]', 'phrasal verb'),
('late payment', '', '', '[{"en":"Late payments by clients disrupted the company cash flow.","zh-TW":"客戶的逾期付款擾亂了公司的現金流。"},{"en":"A late payment fee of 2% per month is applied after 30 days.","zh-TW":"逾期付款後30天起按每月2%計算滯納金。"}]', 'phrasal verb'),
('layoff notice', '', '', '[{"en":"Employees received their layoff notices with four weeks advance warning.","zh-TW":"員工提前四週收到了裁員通知。"},{"en":"A layoff notice must include details of severance and appeal rights.","zh-TW":"裁員通知必須包括遣散費和上訴權的詳情。"}]', 'phrasal verb'),
('lean inventory', '', '', '[{"en":"A lean inventory approach reduces holding costs and waste.","zh-TW":"精益庫存方式降低了持有成本和浪費。"},{"en":"Technology helps companies maintain lean inventory without stockouts.","zh-TW":"技術幫助公司在不缺貨的情況下維持精益庫存。"}]', 'phrasal verb'),
('limited liability company', '', '', '[{"en":"She incorporated a limited liability company to protect personal assets.","zh-TW":"她設立了有限責任公司以保護個人資產。"},{"en":"A limited liability company combines partnership flexibility with corporate protection.","zh-TW":"有限責任公司將合夥靈活性與公司保護相結合。"}]', 'phrasal verb'),
('loan covenant', '', '', '[{"en":"Breaching a loan covenant allows the lender to demand early repayment.","zh-TW":"違反貸款契約條款使貸款方可以要求提前還款。"},{"en":"The company maintained all loan covenants throughout the period.","zh-TW":"公司在整個期間維持了所有貸款契約條款。"}]', 'phrasal verb'),
('loss leader pricing', '', '', '[{"en":"The retailer used loss leader pricing on milk to drive foot traffic.","zh-TW":"零售商對牛奶使用虧本定價以增加客流量。"},{"en":"Loss leader pricing is effective when combined with high-margin add-ons.","zh-TW":"當與高利潤附加品結合時，虧本定價很有效。"}]', 'phrasal verb'),
('management consulting', '', '', '[{"en":"The company hired a management consulting firm to review operations.","zh-TW":"公司聘請了管理諮詢公司審查業務。"},{"en":"Management consulting recommendations led to a 20% cost reduction.","zh-TW":"管理諮詢建議帶來了20%的成本降低。"}]', 'phrasal verb'),
('management report', '', '', '[{"en":"Management reports are prepared monthly to track performance.","zh-TW":"管理報告每月編制以追蹤業績。"},{"en":"The management report highlighted the need to cut discretionary spending.","zh-TW":"管理報告強調了需要削減可裁量支出。"}]', 'phrasal verb'),
('market forces', '', '', '[{"en":"Prices are set by market forces rather than government intervention.","zh-TW":"價格由市場力量而非政府干預決定。"},{"en":"Market forces pushed down the price of smartphones significantly.","zh-TW":"市場力量顯著壓低了智慧型手機的價格。"}]', 'phrasal verb'),
('market position', '', '', '[{"en":"The company strengthened its market position through innovation.","zh-TW":"公司通過創新強化了市場地位。"},{"en":"A strong market position provides pricing power and customer loyalty.","zh-TW":"強大的市場地位提供了定價能力和客戶忠誠度。"}]', 'phrasal verb'),
('market share analysis', '', '', '[{"en":"The market share analysis showed a 5% gain over competitors.","zh-TW":"市場份額分析顯示比競爭對手增加了5%。"},{"en":"Annual market share analysis tracks competitive trends over time.","zh-TW":"年度市場份額分析追蹤競爭趨勢。"}]', 'phrasal verb'),
('market valuation', '', '', '[{"en":"The company market valuation doubled after the product launch.","zh-TW":"產品發佈後，公司市值估算翻了一倍。"},{"en":"Market valuation is used in M&A negotiations to set deal pricing.","zh-TW":"市場估值用於併購談判以設定交易定價。"}]', 'phrasal verb'),
('master agreement', '', '', '[{"en":"The two parties signed a master agreement to govern all future transactions.","zh-TW":"雙方簽署了管理所有未來交易的主協議。"},{"en":"A master agreement simplifies individual transaction documentation.","zh-TW":"主協議簡化了個別交易的文件。"}]', 'phrasal verb'),
('maximization of profit', '', '', '[{"en":"Shareholders expect management to pursue maximization of profit.","zh-TW":"股東期望管理層追求利潤最大化。"},{"en":"Maximization of profit must be balanced against long-term sustainability.","zh-TW":"利潤最大化必須與長期可持續性相平衡。"}]', 'phrasal verb'),
('mentor program', '', '', '[{"en":"The mentor program helped junior staff develop faster.","zh-TW":"導師計劃幫助初級員工更快地發展。"},{"en":"Participation in the mentor program is voluntary but encouraged.","zh-TW":"參與導師計劃是自願的，但受到鼓勵。"}]', 'phrasal verb'),
('minimum wage', '', '', '[{"en":"The government raised the minimum wage for the third consecutive year.","zh-TW":"政府連續第三年提高了最低薪資。"},{"en":"Paying above minimum wage helps companies attract better candidates.","zh-TW":"支付高於最低薪資有助於公司吸引更好的候選人。"}]', 'phrasal verb'),
('multiparty agreement', '', '', '[{"en":"The joint venture required a multiparty agreement between four firms.","zh-TW":"合資企業需要四家公司之間的多方協議。"},{"en":"A multiparty agreement defines each party''s rights and obligations clearly.","zh-TW":"多方協議清楚地定義了各方的權利和義務。"}]', 'phrasal verb'),
('net margin', '', '', '[{"en":"The net margin improved from 6% to 9% after cost cuts.","zh-TW":"成本削減後，淨利率從6%提高到了9%。"},{"en":"A higher net margin indicates more efficient operations.","zh-TW":"較高的淨利率表明運營效率更高。"}]', 'phrasal verb'),
('no-action letter', '', '', '[{"en":"The company received a no-action letter from the regulator.","zh-TW":"公司從監管機構收到了無異議函。"},{"en":"A no-action letter provides regulatory certainty for planned activities.","zh-TW":"無異議函為計劃活動提供了監管確定性。"}]', 'phrasal verb'),
('open-book accounting', '', '', '[{"en":"The construction contract operated on open-book accounting principles.","zh-TW":"建設合約在公開帳目原則下運作。"},{"en":"Open-book accounting builds trust between partners and clients.","zh-TW":"公開帳目在合作夥伴和客戶之間建立信任。"}]', 'phrasal verb'),
('organizational behavior', '', '', '[{"en":"Understanding organizational behavior helps managers improve team effectiveness.","zh-TW":"理解組織行為幫助管理者提高團隊效率。"},{"en":"Organizational behavior research informs leadership development programs.","zh-TW":"組織行為研究為領導力發展計劃提供依據。"}]', 'phrasal verb'),
('periodic payment', '', '', '[{"en":"The loan is repaid through 60 monthly periodic payments.","zh-TW":"貸款通過60個月的定期付款償還。"},{"en":"Periodic payments were adjusted annually for inflation.","zh-TW":"定期付款每年根據通脹調整。"}]', 'phrasal verb'),
('portfolio management', '', '', '[{"en":"Active portfolio management aims to beat the benchmark return.","zh-TW":"主動投資組合管理旨在超越基準回報。"},{"en":"The fund follows a passive portfolio management strategy.","zh-TW":"基金遵循被動投資組合管理策略。"}]', 'phrasal verb'),
('preferred provider', '', '', '[{"en":"Travel bookings must be made through the preferred provider.","zh-TW":"差旅預訂必須通過優先供應商進行。"},{"en":"The preferred provider agreement offered discounted rates for bulk orders.","zh-TW":"優先供應商協議為大量訂購提供了折扣費率。"}]', 'phrasal verb'),
('preliminary agreement', '', '', '[{"en":"A preliminary agreement was signed to secure the exclusive negotiation period.","zh-TW":"簽署了初步協議以確保獨家談判期間。"},{"en":"The preliminary agreement outlined the key commercial terms.","zh-TW":"初步協議概述了主要商業條款。"}]', 'phrasal verb'),
('present value', '', '', '[{"en":"The present value of the future cash flows was 10 million.","zh-TW":"未來現金流的現值為1000萬元。"},{"en":"Present value calculations are essential in investment decision-making.","zh-TW":"現值計算在投資決策中至關重要。"}]', 'phrasal verb'),
('principal amount', '', '', '[{"en":"Monthly payments first cover interest before reducing the principal amount.","zh-TW":"每月付款先支付利息，再減少本金金額。"},{"en":"The principal amount of the bond was 10 million dollars.","zh-TW":"債券的本金金額為1000萬美元。"}]', 'phrasal verb'),
('process improvement', '', '', '[{"en":"Process improvement reduced the order cycle time by 40%.","zh-TW":"流程改善將訂單週期時間縮短了40%。"},{"en":"The lean methodology is widely used for process improvement.","zh-TW":"精益方法論廣泛用於流程改善。"}]', 'phrasal verb'),
('profit motive', '', '', '[{"en":"The profit motive encourages companies to operate efficiently.","zh-TW":"逐利動機促使公司高效運營。"},{"en":"Critics argue the profit motive can conflict with social responsibility.","zh-TW":"批評者認為逐利動機可能與社會責任相衝突。"}]', 'phrasal verb'),
('project lifecycle', '', '', '[{"en":"Each phase of the project lifecycle has defined deliverables.","zh-TW":"項目生命週期的每個階段都有明確的交付成果。"},{"en":"Understanding the project lifecycle improves planning and risk management.","zh-TW":"理解項目生命週期改善了計劃和風險管理。"}]', 'phrasal verb'),
('public procurement', '', '', '[{"en":"Public procurement must follow strict transparency and fairness rules.","zh-TW":"公共採購必須遵守嚴格的透明度和公平性規則。"},{"en":"The company won its largest public procurement contract.","zh-TW":"公司贏得了最大的公共採購合約。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('purchasing power', '', '', '[{"en":"High inflation erodes the purchasing power of consumers.","zh-TW":"高通脹侵蝕了消費者的購買力。"},{"en":"A weaker currency reduces the purchasing power of imports.","zh-TW":"較弱的貨幣降低了進口商品的購買力。"}]', 'phrasal verb'),
('quick ratio', '', '', '[{"en":"A quick ratio above 1 indicates the company can meet short-term obligations.","zh-TW":"速動比率高於1表明公司可以履行短期義務。"},{"en":"The quick ratio declined after large inventory buildup.","zh-TW":"大量庫存積累後，速動比率下降了。"}]', 'phrasal verb'),
('rate of return', '', '', '[{"en":"The investment achieved a rate of return of 12% per year.","zh-TW":"該投資實現了每年12%的報酬率。"},{"en":"A higher rate of return compensates for greater risk taken.","zh-TW":"更高的報酬率補償了承擔的更大風險。"}]', 'phrasal verb'),
('real estate', '', '', '[{"en":"Commercial real estate prices fell during the economic downturn.","zh-TW":"商業房地產價格在經濟低迷期間下跌了。"},{"en":"The company''s real estate portfolio includes offices in five cities.","zh-TW":"公司的房地產投資組合包括五個城市的辦公室。"}]', 'phrasal verb'),
('regional office', '', '', '[{"en":"The company opened a regional office in Singapore to cover Southeast Asia.","zh-TW":"公司在新加坡開設了地區辦公室以覆蓋東南亞。"},{"en":"Regional offices report monthly results to headquarters.","zh-TW":"地區辦公室每月向總部報告業績。"}]', 'phrasal verb'),
('regulatory compliance', '', '', '[{"en":"The company invested in regulatory compliance systems.","zh-TW":"公司投資了監管合規系統。"},{"en":"Failure to achieve regulatory compliance resulted in substantial fines.","zh-TW":"未能達到監管合規導致了重大罰款。"}]', 'phrasal verb'),
('relationship management', '', '', '[{"en":"Strong relationship management led to contract renewals.","zh-TW":"強大的關係管理帶來了合約續期。"},{"en":"CRM software supports relationship management with clients.","zh-TW":"CRM軟體支持與客戶的關係管理。"}]', 'phrasal verb'),
('request for quotation', '', '', '[{"en":"The purchasing team sent a request for quotation to five vendors.","zh-TW":"採購團隊向五家供應商發送了詢價書。"},{"en":"Reviewing multiple quotations ensures competitive pricing.","zh-TW":"審查多份報價確保了有競爭力的定價。"}]', 'phrasal verb'),
('residual value', '', '', '[{"en":"The residual value of leased vehicles was estimated at 30%.","zh-TW":"租賃車輛的殘值估計為30%。"},{"en":"A higher residual value reduces depreciation charges.","zh-TW":"較高的殘值降低了折舊費用。"}]', 'phrasal verb'),
('return on assets', '', '', '[{"en":"The company increased its return on assets by 3% through operational improvements.","zh-TW":"公司通過運營改善將資產回報率提高了3%。"},{"en":"Return on assets is used to compare companies within the same industry.","zh-TW":"資產回報率用於比較同一行業內的公司。"}]', 'phrasal verb'),
('return on capital employed', '', '', '[{"en":"Return on capital employed of 15% exceeded the cost of capital.","zh-TW":"已動用資本回報率15%超過了資本成本。"},{"en":"ROCE is an important metric for capital-intensive industries.","zh-TW":"已動用資本回報率是資本密集型行業的重要指標。"}]', 'phrasal verb'),
('right to work', '', '', '[{"en":"The company respects the right to work for all employees.","zh-TW":"公司尊重所有員工的工作權。"},{"en":"Right to work legislation affects union membership requirements.","zh-TW":"勞動權立法影響了工會成員資格要求。"}]', 'phrasal verb'),
('risk-adjusted return', '', '', '[{"en":"Investors compare risk-adjusted returns to evaluate fund performance.","zh-TW":"投資者比較風險調整後回報以評估基金績效。"},{"en":"A high risk-adjusted return indicates efficient use of risk capital.","zh-TW":"高風險調整後回報表明風險資本使用效率高。"}]', 'phrasal verb'),
('rolling basis', '', '', '[{"en":"Staff are admitted to the program on a rolling basis throughout the year.","zh-TW":"員工在全年滾動基準上入選計劃。"},{"en":"The contract renews automatically on a rolling basis annually.","zh-TW":"合約每年自動以滾動基準續期。"}]', 'phrasal verb'),
('running costs', '', '', '[{"en":"Solar panels reduce the running costs of the factory significantly.","zh-TW":"太陽能板顯著降低了工廠的運營成本。"},{"en":"Running costs must be factored into any financial projection.","zh-TW":"任何財務預測都必須考慮運營成本。"}]', 'phrasal verb'),
('salary review', '', '', '[{"en":"Annual salary reviews are aligned with the company budget cycle.","zh-TW":"年度薪資審查與公司的預算周期相一致。"},{"en":"The salary review resulted in an average 5% increase across the team.","zh-TW":"薪資審查導致整個團隊平均加薪5%。"}]', 'phrasal verb'),
('sales territory', '', '', '[{"en":"Each sales rep is responsible for a specific sales territory.","zh-TW":"每位銷售代表負責特定的銷售區域。"},{"en":"Expanding sales territories is a sign of business growth.","zh-TW":"擴大銷售區域是業務增長的標誌。"}]', 'phrasal verb'),
('search engine optimization', '', '', '[{"en":"Search engine optimization increased organic traffic by 80%.","zh-TW":"搜尋引擎優化使自然流量增加了80%。"},{"en":"Content quality is the most important factor in search engine optimization.","zh-TW":"內容品質是搜尋引擎優化中最重要的因素。"}]', 'phrasal verb'),
('share buyback', '', '', '[{"en":"The board authorized a 50 million dollar share buyback program.","zh-TW":"董事會授權了5000萬美元的股份回購計劃。"},{"en":"A share buyback reduces the number of outstanding shares.","zh-TW":"股份回購減少了流通股數量。"}]', 'phrasal verb'),
('share capital', '', '', '[{"en":"The company raised its share capital through a rights issue.","zh-TW":"公司通過配股增加了股本。"},{"en":"Share capital represents the owners investment in the business.","zh-TW":"股本代表了業主對企業的投資。"}]', 'phrasal verb'),
('short-term investment', '', '', '[{"en":"The company held short-term investments in treasury bills.","zh-TW":"公司持有國庫券等短期投資。"},{"en":"Short-term investments are classified as current assets.","zh-TW":"短期投資歸類為流動資產。"}]', 'phrasal verb'),
('skilled labor', '', '', '[{"en":"The shortage of skilled labor pushed wages higher in the construction sector.","zh-TW":"技術工人短缺推高了建築行業的工資。"},{"en":"Investing in training develops skilled labor from existing employees.","zh-TW":"投資培訓從現有員工中培養技術工人。"}]', 'phrasal verb'),
('smart technology', '', '', '[{"en":"Smart technology improved energy efficiency across the factory.","zh-TW":"智慧科技提高了整個工廠的能源效率。"},{"en":"The company invested in smart technology to automate manual processes.","zh-TW":"公司投資智慧科技以自動化人工流程。"}]', 'phrasal verb'),
('sole trader', '', '', '[{"en":"As a sole trader, all profits are taxed as personal income.","zh-TW":"作為個體戶，所有利潤作為個人收入徵稅。"},{"en":"A sole trader has full control but unlimited personal liability.","zh-TW":"個體戶擁有完全控制權但承擔無限個人責任。"}]', 'phrasal verb'),
('spot price', '', '', '[{"en":"The spot price of oil rose to 90 dollars per barrel.","zh-TW":"原油即期價格漲至每桶90美元。"},{"en":"Buyers prefer spot price purchases when the market is declining.","zh-TW":"當市場下跌時，買方偏好以即期價格購買。"}]', 'phrasal verb'),
('staff turnover', '', '', '[{"en":"A high staff turnover is costly and disrupts operations.","zh-TW":"高員工流動率成本高昂並擾亂運營。"},{"en":"Improved working conditions helped reduce staff turnover by 20%.","zh-TW":"改善工作條件幫助將員工流動率降低了20%。"}]', 'phrasal verb'),
('strategic investment', '', '', '[{"en":"The company made a strategic investment in its competitor to gain access.","zh-TW":"公司對競爭對手進行了戰略投資以獲取市場准入。"},{"en":"Strategic investments are evaluated on qualitative as well as financial criteria.","zh-TW":"戰略投資根據定性和財務標準進行評估。"}]', 'phrasal verb'),
('subscription fee', '', '', '[{"en":"The platform charges a monthly subscription fee of 15 dollars.","zh-TW":"平台收取每月15美元的訂閱費。"},{"en":"The subscription fee was reduced for annual payment plans.","zh-TW":"年度付款計劃的訂閱費降低了。"}]', 'phrasal verb'),
('supplier audit', '', '', '[{"en":"The procurement team conducted surprise supplier audits twice a year.","zh-TW":"採購團隊每年進行兩次突擊供應商審計。"},{"en":"A supplier audit revealed substandard conditions in the factory.","zh-TW":"供應商審計揭示了工廠中低於標準的條件。"}]', 'phrasal verb'),
('target setting', '', '', '[{"en":"The target setting process aligns team goals with company objectives.","zh-TW":"目標設定流程使團隊目標與公司目標保持一致。"},{"en":"Realistic target setting motivates employees without creating undue pressure.","zh-TW":"現實的目標設定在不造成過度壓力的情況下激勵員工。"}]', 'phrasal verb'),
('tax planning', '', '', '[{"en":"The accountant provided tax planning advice for the year ahead.","zh-TW":"會計師為未來一年提供了稅務規劃建議。"},{"en":"Proactive tax planning can significantly reduce the annual tax bill.","zh-TW":"主動的稅務規劃可以顯著降低年度稅務帳單。"}]', 'phrasal verb'),
('tax relief', '', '', '[{"en":"Small businesses can claim tax relief on new equipment purchases.","zh-TW":"小企業可以就新設備採購申請稅務減免。"},{"en":"Tax relief for charitable donations encourages corporate philanthropy.","zh-TW":"慈善捐款的稅務減免鼓勵了企業慈善事業。"}]', 'phrasal verb'),
('tender process', '', '', '[{"en":"The tender process requires submission of detailed technical proposals.","zh-TW":"招標流程要求提交詳細的技術建議書。"},{"en":"A transparent tender process ensures fair competition among suppliers.","zh-TW":"透明的招標流程確保了供應商之間的公平競爭。"}]', 'phrasal verb'),
('top management', '', '', '[{"en":"Top management approved the multi-year investment plan.","zh-TW":"最高管理層批准了多年投資計劃。"},{"en":"Changes of this scale require buy-in from top management.","zh-TW":"這種規模的變化需要最高管理層的支持。"}]', 'phrasal verb'),
('total return', '', '', '[{"en":"The bond''s total return over three years was 18%.","zh-TW":"債券三年的總回報為18%。"},{"en":"A total return approach considers both dividends and price appreciation.","zh-TW":"總回報方法同時考慮股息和價格升值。"}]', 'phrasal verb'),
('trade payables', '', '', '[{"en":"Extending trade payables terms improved working capital.","zh-TW":"延長應付帳款條款改善了營運資金。"},{"en":"Trade payables are listed as current liabilities on the balance sheet.","zh-TW":"應付帳款在資產負債表上列為流動負債。"}]', 'phrasal verb'),
('utility cost', '', '', '[{"en":"Energy efficiency measures reduced utility costs by 15%.","zh-TW":"能源效率措施將水電費降低了15%。"},{"en":"Utility costs are included in the monthly fixed overhead.","zh-TW":"水電費包含在每月固定間接費用中。"}]', 'phrasal verb'),
('value investing', '', '', '[{"en":"Value investing involves buying stocks trading below their intrinsic value.","zh-TW":"價值投資涉及購買交易價格低於其內在價值的股票。"},{"en":"Warren Buffett is widely regarded as the champion of value investing.","zh-TW":"沃倫·巴菲特被廣泛視為價值投資的倡導者。"}]', 'phrasal verb'),
('variance analysis', '', '', '[{"en":"Variance analysis showed that sales volumes were 10% below budget.","zh-TW":"差異分析顯示銷售量低於預算10%。"},{"en":"Monthly variance analysis helps management respond quickly to deviations.","zh-TW":"月度差異分析幫助管理層快速回應偏差。"}]', 'phrasal verb'),
('verbal agreement', '', '', '[{"en":"Although a verbal agreement was reached, a formal contract was still needed.","zh-TW":"雖然達成了口頭協議，但仍需要正式合約。"},{"en":"A verbal agreement may be enforceable but is difficult to prove.","zh-TW":"口頭協議可能具有可執行性，但難以證明。"}]', 'phrasal verb'),
('vice president', '', '', '[{"en":"She was promoted to vice president of marketing after three years.","zh-TW":"她三年後晉升為行銷副總裁。"},{"en":"The vice president presented the strategic plan to the board.","zh-TW":"副總裁向董事會提交了戰略計劃。"}]', 'phrasal verb'),
('wage growth', '', '', '[{"en":"Strong wage growth boosted consumer spending.","zh-TW":"強勁的薪資增長提升了消費者支出。"},{"en":"Wage growth lagged behind inflation, reducing real purchasing power.","zh-TW":"薪資增長落後於通脹，降低了實際購買力。"}]', 'phrasal verb'),
('wealth accumulation', '', '', '[{"en":"Long-term investment is the most reliable path to wealth accumulation.","zh-TW":"長期投資是財富積累最可靠的途徑。"},{"en":"Compound interest is a powerful tool for wealth accumulation.","zh-TW":"複利是財富積累的強大工具。"}]', 'phrasal verb'),
('weighted average cost of capital', '', '', '[{"en":"Projects must exceed the weighted average cost of capital to create value.","zh-TW":"項目必須超過加權平均資本成本才能創造價值。"},{"en":"The WACC is used as the discount rate in DCF valuations.","zh-TW":"加權平均資本成本用作折現現金流估值中的折現率。"}]', 'phrasal verb'),
('work breakdown structure', '', '', '[{"en":"The work breakdown structure was used to assign tasks and estimate costs.","zh-TW":"工作分解結構用於分配任務和估算成本。"},{"en":"A detailed work breakdown structure improves project planning accuracy.","zh-TW":"詳細的工作分解結構提高了項目計劃的準確性。"}]', 'phrasal verb'),
('working remotely', '', '', '[{"en":"The team has been working remotely since the pandemic.","zh-TW":"自疫情以來，團隊一直在遠程辦公。"},{"en":"Working remotely requires strong self-discipline and clear communication.","zh-TW":"遠程辦公需要強大的自律和清晰的溝通。"}]', 'phrasal verb'),
('written consent', '', '', '[{"en":"Written consent from the landlord is needed before subletting.","zh-TW":"轉租前需要獲得房東的書面同意。"},{"en":"The data collection requires written consent from each participant.","zh-TW":"資料收集需要每位參與者的書面同意。"}]', 'phrasal verb'),
('authorized dealer', '', '', '[{"en":"Only purchase from an authorized dealer to ensure product authenticity.","zh-TW":"只從授權經銷商購買以確保產品真實性。"},{"en":"The authorized dealer program expanded to 50 locations.","zh-TW":"授權經銷商計劃擴展到了50個地點。"}]', 'phrasal verb'),
('bank guarantee', '', '', '[{"en":"A bank guarantee was required before the construction contract was awarded.","zh-TW":"在授予建設合約前需要銀行擔保。"},{"en":"The bank guarantee protected the developer against contractor default.","zh-TW":"銀行擔保保護了開發商免受承包商違約的影響。"}]', 'phrasal verb'),
('bank reconciliation', '', '', '[{"en":"Bank reconciliation is performed every month to verify accuracy.","zh-TW":"每月進行銀行對帳以核實準確性。"},{"en":"The bank reconciliation identified a double payment of 5000.","zh-TW":"銀行對帳識別了一筆5000元的雙重付款。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('bank statement', '', '', '[{"en":"The accountant reviewed the bank statement to find the discrepancy.","zh-TW":"會計師審查了銀行對帳單以找出差異。"},{"en":"Monthly bank statements are essential for accurate bookkeeping.","zh-TW":"每月銀行對帳單對準確記帳至關重要。"}]', 'phrasal verb'),
('best practices', '', '', '[{"en":"The company adopted best practices from the manufacturing sector.","zh-TW":"公司採用了製造業的最佳實踐。"},{"en":"Sharing best practices across departments improves overall performance.","zh-TW":"跨部門分享最佳實踐改善了整體績效。"}]', 'phrasal verb'),
('bond yield', '', '', '[{"en":"A rising bond yield makes bonds more attractive to investors.","zh-TW":"上升的債券收益率使債券對投資者更具吸引力。"},{"en":"The government bond yield fell to a record low during the crisis.","zh-TW":"危機期間，政府債券收益率降至歷史最低點。"}]', 'phrasal verb'),
('breakout strategy', '', '', '[{"en":"The breakout strategy targeted three new international markets.","zh-TW":"突破策略針對了三個新的國際市場。"},{"en":"A bold breakout strategy reversed five years of declining sales.","zh-TW":"大膽的突破策略扭轉了五年的銷售下滑。"}]', 'phrasal verb'),
('budget approval', '', '', '[{"en":"All projects require budget approval before commencement.","zh-TW":"所有項目在開始前都需要預算批准。"},{"en":"Budget approval for the capital project was granted by the board.","zh-TW":"資本項目的預算批准由董事會授予。"}]', 'phrasal verb'),
('call option', '', '', '[{"en":"Investors bought call options to profit from an expected price rise.","zh-TW":"投資者購買了認購期權以從預期的價格上漲中獲利。"},{"en":"Call options are used to hedge against rising input costs.","zh-TW":"認購期權用於對沖上漲的投入成本。"}]', 'phrasal verb'),
('cash management', '', '', '[{"en":"Effective cash management ensures bills are paid on time.","zh-TW":"有效的現金管理確保按時支付賬單。"},{"en":"The treasury function oversees all cash management activities.","zh-TW":"財資職能監督所有現金管理活動。"}]', 'phrasal verb'),
('chief executive officer', '', '', '[{"en":"The new CEO outlined a bold transformation strategy.","zh-TW":"新任執行長概述了大膽的轉型策略。"},{"en":"The chief executive officer reported quarterly results to the board.","zh-TW":"執行長向董事會報告了季度業績。"}]', 'phrasal verb'),
('chief operating officer', '', '', '[{"en":"The chief operating officer managed all production and logistics.","zh-TW":"首席運營官管理所有生產和物流。"},{"en":"The COO implemented the new operational efficiency program.","zh-TW":"首席運營官實施了新的運營效率計劃。"}]', 'phrasal verb'),
('city centre', '', '', '[{"en":"The new office is located in the city centre for client accessibility.","zh-TW":"新辦公室位於市中心，方便客戶到訪。"},{"en":"City centre retail rents are significantly higher than suburban locations.","zh-TW":"市中心零售租金顯著高於郊區地點。"}]', 'phrasal verb'),
('class action', '', '', '[{"en":"A class action was launched against the company for misleading advertising.","zh-TW":"針對公司誤導性廣告的集體訴訟被提起了。"},{"en":"The class action settlement cost the company 50 million.","zh-TW":"集體訴訟和解使公司付出了5000萬元的代價。"}]', 'phrasal verb'),
('client base', '', '', '[{"en":"The company grew its client base from 50 to 200 in two years.","zh-TW":"公司在兩年內將客戶群從50家增長到了200家。"},{"en":"A diverse client base protects against revenue concentration risk.","zh-TW":"多元化的客戶群防止了收入集中風險。"}]', 'phrasal verb'),
('closing balance', '', '', '[{"en":"The closing balance of the account was 15000 dollars.","zh-TW":"帳戶的期末餘額為15000美元。"},{"en":"The closing balance is carried forward as the opening balance.","zh-TW":"期末餘額結轉為下期期初餘額。"}]', 'phrasal verb'),
('cloud storage', '', '', '[{"en":"The company migrated all documents to cloud storage for remote access.","zh-TW":"公司將所有文件遷移到雲端儲存以便遠程存取。"},{"en":"Cloud storage reduces the need for physical server infrastructure.","zh-TW":"雲端儲存減少了對物理伺服器基礎設施的需求。"}]', 'phrasal verb'),
('collective action', '', '', '[{"en":"Collective action by suppliers led to better payment terms.","zh-TW":"供應商的集體行動帶來了更好的付款條款。"},{"en":"Solving climate change requires collective action across industries.","zh-TW":"解決氣候變化需要跨行業的集體行動。"}]', 'phrasal verb'),
('commercial agreement', '', '', '[{"en":"The commercial agreement covered pricing, delivery, and warranty terms.","zh-TW":"商業協議涵蓋了定價、交貨和保修條款。"},{"en":"A commercial agreement was signed to formalize the distribution arrangement.","zh-TW":"簽署了商業協議以正式確認分銷安排。"}]', 'phrasal verb'),
('commitment to quality', '', '', '[{"en":"The manufacturer''s commitment to quality earned it multiple certifications.","zh-TW":"製造商的品質承諾為其贏得了多項認證。"},{"en":"A commitment to quality is central to the company brand promise.","zh-TW":"品質承諾是公司品牌承諾的核心。"}]', 'phrasal verb'),
('competitive pressure', '', '', '[{"en":"Competitive pressure forced the company to reduce prices.","zh-TW":"競爭壓力迫使公司降低了價格。"},{"en":"Competitive pressure drove investment in innovation and efficiency.","zh-TW":"競爭壓力推動了對創新和效率的投資。"}]', 'phrasal verb'),
('concentration risk', '', '', '[{"en":"The company reduced concentration risk by diversifying its supplier base.","zh-TW":"公司通過多元化供應商基礎降低了集中風險。"},{"en":"Concentration risk is high when 50% of revenue comes from one client.","zh-TW":"當50%的收入來自一個客戶時，集中風險很高。"}]', 'phrasal verb'),
('consignment note', '', '', '[{"en":"A consignment note was issued for each shipment.","zh-TW":"每批貨物都簽發了一份運貨單。"},{"en":"The consignment note details the contents, weight, and destination.","zh-TW":"運貨單詳列了內容物、重量和目的地。"}]', 'phrasal verb'),
('consulting assignment', '', '', '[{"en":"The consulting assignment lasted six months and covered operations.","zh-TW":"諮詢任務持續了六個月並涵蓋了業務。"},{"en":"The firm accepted the consulting assignment on a fixed-fee basis.","zh-TW":"公司以固定費用基礎接受了諮詢任務。"}]', 'phrasal verb'),
('continuous improvement', '', '', '[{"en":"A culture of continuous improvement drives long-term competitiveness.","zh-TW":"持續改善的文化推動了長期競爭力。"},{"en":"The manufacturing team uses Kaizen for continuous improvement.","zh-TW":"製造團隊使用改善（Kaizen）進行持續改善。"}]', 'phrasal verb'),
('control environment', '', '', '[{"en":"A strong control environment reduces the risk of fraud.","zh-TW":"強大的控制環境降低了欺詐風險。"},{"en":"The audit highlighted weaknesses in the control environment.","zh-TW":"審計指出了控制環境中的薄弱環節。"}]', 'phrasal verb'),
('convenience store', '', '', '[{"en":"The convenience store chain expanded to 1000 locations nationally.","zh-TW":"便利店連鎖擴展到了全國1000個地點。"},{"en":"Convenience stores generate high revenue per square meter.","zh-TW":"便利店每平方米產生的收入很高。"}]', 'phrasal verb'),
('corporate income tax', '', '', '[{"en":"The corporate income tax rate was reduced to attract investment.","zh-TW":"企業所得稅率降低以吸引投資。"},{"en":"Companies must file corporate income tax returns annually.","zh-TW":"公司必須每年申報企業所得稅。"}]', 'phrasal verb'),
('cost recovery', '', '', '[{"en":"The project reached full cost recovery in its third year.","zh-TW":"項目在第三年達到了完全成本回收。"},{"en":"Cost recovery is built into the pricing model from the start.","zh-TW":"成本回收從一開始就被納入了定價模型。"}]', 'phrasal verb'),
('courier service', '', '', '[{"en":"The document was sent by courier service for next-day delivery.","zh-TW":"文件通過快遞服務以次日達方式寄送。"},{"en":"The company uses a courier service for urgent contract deliveries.","zh-TW":"公司使用快遞服務進行緊急合約交付。"}]', 'phrasal verb'),
('cross-border transaction', '', '', '[{"en":"Cross-border transactions are subject to currency conversion fees.","zh-TW":"跨境交易須支付貨幣轉換費。"},{"en":"Regulatory compliance for cross-border transactions varies by country.","zh-TW":"跨境交易的監管合規因國家而異。"}]', 'phrasal verb'),
('current account', '', '', '[{"en":"The company holds most operating funds in a current account.","zh-TW":"公司在往來帳戶中持有大部分運營資金。"},{"en":"A current account deficit means a country imports more than it exports.","zh-TW":"往來帳戶逆差意味著一個國家的進口多於出口。"}]', 'phrasal verb'),
('customer complaint', '', '', '[{"en":"Each customer complaint is logged and reviewed within 24 hours.","zh-TW":"每個客戶投訴都在24小時內記錄和審查。"},{"en":"A spike in customer complaints signals a quality or service issue.","zh-TW":"客戶投訴激增表明有品質或服務問題。"}]', 'phrasal verb'),
('customer onboarding', '', '', '[{"en":"A smooth customer onboarding experience reduces early churn.","zh-TW":"順暢的客戶入門體驗降低了早期流失率。"},{"en":"Customer onboarding includes welcome emails, tutorials, and support.","zh-TW":"客戶入門包括歡迎電子郵件、教程和支援。"}]', 'phrasal verb'),
('cut costs', '', '', '[{"en":"The company cut costs by reducing travel and entertainment expenses.","zh-TW":"公司通過減少差旅和娛樂費用削減了成本。"},{"en":"Cutting costs without affecting quality is a major management challenge.","zh-TW":"在不影響品質的情況下削減成本是一大管理挑戰。"}]', 'phrasal verb'),
('data entry', '', '', '[{"en":"Automating data entry reduced processing time by 60%.","zh-TW":"自動化資料輸入將處理時間縮短了60%。"},{"en":"Data entry errors were the main cause of reconciliation differences.","zh-TW":"資料輸入錯誤是對帳差異的主要原因。"}]', 'phrasal verb'),
('data management', '', '', '[{"en":"Good data management ensures reliable reporting.","zh-TW":"良好的資料管理確保了可靠的報告。"},{"en":"Data management practices must comply with privacy regulations.","zh-TW":"資料管理實踐必須遵守隱私法規。"}]', 'phrasal verb'),
('dealing room', '', '', '[{"en":"The dealing room handles over 10 billion in daily transactions.","zh-TW":"交易室每天處理超過100億元的交易。"},{"en":"Electronic trading has reduced the size of many dealing rooms.","zh-TW":"電子交易縮小了許多交易室的規模。"}]', 'phrasal verb'),
('deferred payment', '', '', '[{"en":"The company offered customers a deferred payment plan on large orders.","zh-TW":"公司向客戶提供了大額訂單的延期付款計劃。"},{"en":"Deferred payment helps clients manage cash flow on major purchases.","zh-TW":"延期付款幫助客戶管理重大採購的現金流。"}]', 'phrasal verb'),
('depreciation expense', '', '', '[{"en":"Depreciation expense reduced the company operating income.","zh-TW":"折舊費用降低了公司的營業收入。"},{"en":"An accountant calculates the annual depreciation expense for each asset.","zh-TW":"會計師計算每項資產的年度折舊費用。"}]', 'phrasal verb'),
('development plan', '', '', '[{"en":"Each employee has a personal development plan reviewed annually.","zh-TW":"每位員工都有每年審查的個人發展計劃。"},{"en":"The development plan covered skills training and leadership development.","zh-TW":"發展計劃涵蓋了技能培訓和領導力發展。"}]', 'phrasal verb'),
('differentiated product', '', '', '[{"en":"The company launched a differentiated product with a unique design.","zh-TW":"公司推出了具有獨特設計的差異化產品。"},{"en":"Differentiated products can support higher pricing and brand loyalty.","zh-TW":"差異化產品可以支持更高定價和品牌忠誠度。"}]', 'phrasal verb'),
('digital infrastructure', '', '', '[{"en":"Investing in digital infrastructure is essential for long-term competitiveness.","zh-TW":"投資數位基礎設施對長期競爭力至關重要。"},{"en":"Weak digital infrastructure creates bottlenecks in operations.","zh-TW":"薄弱的數位基礎設施在運營中造成瓶頸。"}]', 'phrasal verb'),
('direct debit', '', '', '[{"en":"Utility bills are paid by direct debit on the first of each month.","zh-TW":"水電費在每月第一日通過直接扣帳支付。"},{"en":"Setting up a direct debit ensures bills are never missed.","zh-TW":"設置直接扣帳確保永遠不會錯過賬單。"}]', 'phrasal verb'),
('direct marketing', '', '', '[{"en":"Direct marketing via email generated a 10% response rate.","zh-TW":"通過電子郵件的直效行銷產生了10%的回應率。"},{"en":"A direct marketing campaign targeted previous customers with special offers.","zh-TW":"直效行銷活動以特別優惠針對了以前的客戶。"}]', 'phrasal verb'),
('disbursement schedule', '', '', '[{"en":"The disbursement schedule tied payments to project completion milestones.","zh-TW":"付款計劃將付款與項目完成里程碑相關聯。"},{"en":"The bank required a disbursement schedule before releasing funds.","zh-TW":"銀行在釋放資金前需要付款計劃。"}]', 'phrasal verb'),
('discount rate', '', '', '[{"en":"A higher discount rate reduces the present value of future earnings.","zh-TW":"較高的折現率降低了未來收益的現值。"},{"en":"The discount rate reflects the risk associated with the investment.","zh-TW":"折現率反映了與投資相關的風險。"}]', 'phrasal verb'),
('disclosure policy', '', '', '[{"en":"The listed company updated its disclosure policy after new regulations.","zh-TW":"上市公司在新法規後更新了其披露政策。"},{"en":"A clear disclosure policy builds investor confidence.","zh-TW":"清晰的披露政策建立了投資者信心。"}]', 'phrasal verb'),
('distribution network', '', '', '[{"en":"The company invested in building a nationwide distribution network.","zh-TW":"公司投資於建立全國性分銷網路。"},{"en":"A strong distribution network is a competitive advantage in retail.","zh-TW":"強大的分銷網路是零售業的競爭優勢。"}]', 'phrasal verb'),
('draft budget', '', '', '[{"en":"The draft budget was presented to the finance committee in November.","zh-TW":"預算草案在十一月提交給了財務委員會。"},{"en":"Several revisions were made before the draft budget was approved.","zh-TW":"預算草案在批准前進行了幾次修訂。"}]', 'phrasal verb'),
('efficiency savings', '', '', '[{"en":"The merger delivered 30 million in annual efficiency savings.","zh-TW":"合並帶來了每年3000萬元的效率節省。"},{"en":"Technology investment contributed significantly to efficiency savings.","zh-TW":"技術投資顯著促進了效率節省。"}]', 'phrasal verb'),
('embargo period', '', '', '[{"en":"Financial results are under an embargo period before the announcement.","zh-TW":"財務業績在公告前處於禁止期。"},{"en":"Press releases are shared in advance with an embargo period attached.","zh-TW":"新聞稿提前共享，並附有禁止期。"}]', 'phrasal verb'),
('employment agency', '', '', '[{"en":"The company used an employment agency to fill specialist roles.","zh-TW":"公司通過職業介紹所填補了專業職位。"},{"en":"Employment agencies charge a placement fee based on salary.","zh-TW":"職業介紹所根據薪資收取安置費。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('end of contract', '', '', '[{"en":"She received a bonus at the end of her three-year contract.","zh-TW":"她在三年合約期滿時收到了獎金。"},{"en":"End of contract procedures include final settlement and document return.","zh-TW":"合約期滿程序包括最終結算和文件歸還。"}]', 'phrasal verb'),
('equity dilution', '', '', '[{"en":"A large funding round caused significant equity dilution for founders.","zh-TW":"大規模融資輪次對創辦人造成了顯著的股權稀釋。"},{"en":"Anti-dilution provisions protect investors from equity dilution.","zh-TW":"反稀釋條款保護投資者免受股權稀釋影響。"}]', 'phrasal verb'),
('ethics code', '', '', '[{"en":"All staff are required to sign the ethics code annually.","zh-TW":"所有員工每年必須簽署道德準則。"},{"en":"The ethics code prohibits accepting gifts from suppliers.","zh-TW":"道德準則禁止接受供應商的禮物。"}]', 'phrasal verb'),
('expansion funding', '', '', '[{"en":"The company secured 15 million in expansion funding.","zh-TW":"公司獲得了1500萬元的擴張資金。"},{"en":"Expansion funding was used to open three new regional offices.","zh-TW":"擴張資金用於開設三個新的區域辦公室。"}]', 'phrasal verb'),
('expenditure plan', '', '', '[{"en":"The department submitted its expenditure plan for the next fiscal year.","zh-TW":"部門提交了下一財政年度的支出計劃。"},{"en":"The expenditure plan was revised to align with budget constraints.","zh-TW":"支出計劃修訂以符合預算限制。"}]', 'phrasal verb'),
('facility agreement', '', '', '[{"en":"The facility agreement provided a 20 million revolving credit line.","zh-TW":"融資安排協議提供了2000萬元的循環信貸額度。"},{"en":"A facility agreement defines the borrowing limit, interest, and conditions.","zh-TW":"融資安排協議定義了借款限額、利息和條件。"}]', 'phrasal verb'),
('fair market value', '', '', '[{"en":"The property was sold at fair market value after an independent valuation.","zh-TW":"在獨立估值後，房產以公平市場價值出售了。"},{"en":"Tax authorities use fair market value to assess capital gains.","zh-TW":"稅務機關使用公平市場價值來評估資本利得。"}]', 'phrasal verb'),
('financial accounting', '', '', '[{"en":"Financial accounting is governed by international reporting standards.","zh-TW":"財務會計受國際報告準則的約束。"},{"en":"The external auditor reviewed the financial accounting records.","zh-TW":"外部審計師審查了財務會計記錄。"}]', 'phrasal verb'),
('financial assets', '', '', '[{"en":"The company holds financial assets worth 100 million on its balance sheet.","zh-TW":"公司在資產負債表上持有價值1億元的金融資產。"},{"en":"Financial assets include cash, bonds, and equity holdings.","zh-TW":"金融資產包括現金、債券和股權持有。"}]', 'phrasal verb'),
('financial exposure', '', '', '[{"en":"The company reduced its financial exposure to foreign exchange risk.","zh-TW":"公司降低了對外匯風險的財務風險敞口。"},{"en":"Financial exposure to a single customer should not exceed 30%.","zh-TW":"對單一客戶的財務風險敞口不應超過30%。"}]', 'phrasal verb'),
('financial planning', '', '', '[{"en":"The CFO led the annual financial planning process.","zh-TW":"財務長主導了年度財務規劃流程。"},{"en":"Effective financial planning requires accurate forecasting and scenario analysis.","zh-TW":"有效的財務規劃需要準確的預測和情境分析。"}]', 'phrasal verb'),
('fixed costs', '', '', '[{"en":"Rent and salaries are the largest fixed costs for most businesses.","zh-TW":"租金和薪資是大多數企業最大的固定成本。"},{"en":"Reducing fixed costs is critical during a revenue downturn.","zh-TW":"在收入低迷期間降低固定成本至關重要。"}]', 'phrasal verb'),
('flexible workforce', '', '', '[{"en":"A flexible workforce allows the company to respond to seasonal demand.","zh-TW":"靈活勞動力使公司能夠應對季節性需求。"},{"en":"Contract workers contribute to a more flexible workforce.","zh-TW":"合約工人為更靈活的勞動力做出了貢獻。"}]', 'phrasal verb'),
('forecast model', '', '', '[{"en":"The forecast model predicted revenue within 5% of actual.","zh-TW":"預測模型對收入的預測誤差在實際5%以內。"},{"en":"Machine learning improved the company forecast model significantly.","zh-TW":"機器學習顯著改善了公司的預測模型。"}]', 'phrasal verb'),
('framework agreement', '', '', '[{"en":"A framework agreement was established for all software purchases.","zh-TW":"為所有軟體採購建立了框架協議。"},{"en":"The framework agreement simplified the procurement of recurring services.","zh-TW":"框架協議簡化了定期服務的採購。"}]', 'phrasal verb'),
('full-year results', '', '', '[{"en":"Full-year results showed a 15% increase in net profit.","zh-TW":"全年業績顯示淨利潤增加了15%。"},{"en":"Investors focused on full-year results to assess the CEO strategy.","zh-TW":"投資者關注全年業績以評估執行長的策略。"}]', 'phrasal verb'),
('functional area', '', '', '[{"en":"Each functional area submitted its budget request to finance.","zh-TW":"每個職能領域向財務部門提交了預算申請。"},{"en":"The new system affected every functional area in the company.","zh-TW":"新系統影響了公司的每個職能領域。"}]', 'phrasal verb'),
('general manager', '', '', '[{"en":"The general manager reviewed performance results with each department.","zh-TW":"總經理與每個部門回顧了績效結果。"},{"en":"She was appointed as general manager for the Asian division.","zh-TW":"她被任命為亞洲部門的總經理。"}]', 'phrasal verb'),
('global reach', '', '', '[{"en":"The company expanded its global reach through an international partnership.","zh-TW":"公司通過國際夥伴關係擴大了其全球覆蓋。"},{"en":"Social media gives small businesses global reach at low cost.","zh-TW":"社群媒體讓小企業以低成本實現全球覆蓋。"}]', 'phrasal verb'),
('goal setting', '', '', '[{"en":"Goal setting at the start of the year aligns teams on priorities.","zh-TW":"年初的目標設定使各團隊在優先事項上保持一致。"},{"en":"SMART goal setting makes objectives specific, measurable, and time-bound.","zh-TW":"SMART目標設定使目標具體、可衡量且有時限。"}]', 'phrasal verb'),
('government subsidy', '', '', '[{"en":"The renewable energy sector received government subsidies to grow.","zh-TW":"可再生能源行業獲得了政府補貼以促進增長。"},{"en":"Government subsidies distort competition if not applied carefully.","zh-TW":"如果應用不當，政府補貼會扭曲競爭。"}]', 'phrasal verb'),
('grace period', '', '', '[{"en":"The lender granted a 15-day grace period on the late payment.","zh-TW":"貸款方對逾期付款給予了15天的寬限期。"},{"en":"Insurance policies include a grace period for premium payments.","zh-TW":"保險政策包含保費支付的寬限期。"}]', 'phrasal verb'),
('growth potential', '', '', '[{"en":"The emerging market segment has significant growth potential.","zh-TW":"新興市場細分具有顯著的增長潛力。"},{"en":"The startup''s growth potential attracted venture capital investment.","zh-TW":"新創公司的增長潛力吸引了創業投資。"}]', 'phrasal verb'),
('group performance', '', '', '[{"en":"Group performance improved 12% year on year.","zh-TW":"集團業績同比提升了12%。"},{"en":"The annual report consolidates group performance across all regions.","zh-TW":"年報整合了所有地區的集團業績。"}]', 'phrasal verb'),
('high net worth', '', '', '[{"en":"Wealth management services target high net worth individuals.","zh-TW":"財富管理服務針對高淨值人士。"},{"en":"High net worth clients receive dedicated private banking services.","zh-TW":"高淨值客戶獲得專屬的私人銀行服務。"}]', 'phrasal verb'),
('import duty exemption', '', '', '[{"en":"Manufacturers in export zones benefit from import duty exemptions.","zh-TW":"出口區的製造商受益於進口關稅豁免。"},{"en":"An import duty exemption was granted for raw materials used in production.","zh-TW":"對用於生產的原材料給予了進口關稅豁免。"}]', 'phrasal verb'),
('inbound logistics', '', '', '[{"en":"Streamlining inbound logistics cut warehouse receiving time in half.","zh-TW":"簡化進貨物流將倉庫收貨時間縮短了一半。"},{"en":"Inbound logistics efficiency is critical for just-in-time manufacturing.","zh-TW":"進貨物流效率對即時生產至關重要。"}]', 'phrasal verb'),
('insider trading', '', '', '[{"en":"The executive was charged with insider trading after buying shares before the merger.","zh-TW":"高管在合並前購買股票後被指控內線交易。"},{"en":"Insider trading undermines investor confidence in capital markets.","zh-TW":"內線交易破壞了投資者對資本市場的信心。"}]', 'phrasal verb'),
('intellectual asset', '', '', '[{"en":"Patents and trade secrets are valuable intellectual assets.","zh-TW":"專利和商業機密是有價值的知識資產。"},{"en":"The company''s intellectual assets include proprietary software.","zh-TW":"公司的知識資產包括專有軟體。"}]', 'phrasal verb'),
('inventory count', '', '', '[{"en":"The warehouse team completed the annual inventory count overnight.","zh-TW":"倉庫團隊連夜完成了年度庫存盤點。"},{"en":"Inventory count discrepancies are investigated immediately.","zh-TW":"庫存盤點差異立即進行調查。"}]', 'phrasal verb'),
('investment committee', '', '', '[{"en":"All major investments require investment committee approval.","zh-TW":"所有重大投資都需要投資委員會批准。"},{"en":"The investment committee met quarterly to review the portfolio.","zh-TW":"投資委員會每季召開會議審查投資組合。"}]', 'phrasal verb'),
('investment strategy', '', '', '[{"en":"The fund''s investment strategy balances growth and income.","zh-TW":"基金的投資策略在增長和收入之間取得平衡。"},{"en":"A long-term investment strategy outperforms short-term trading.","zh-TW":"長期投資策略優於短期交易。"}]', 'phrasal verb'),
('invoice reconciliation', '', '', '[{"en":"Invoice reconciliation prevents duplicate or incorrect payments.","zh-TW":"發票核對防止了重複或錯誤付款。"},{"en":"The accounts team performs invoice reconciliation weekly.","zh-TW":"帳務團隊每週進行發票核對。"}]', 'phrasal verb'),
('joint venture agreement', '', '', '[{"en":"Both companies signed a joint venture agreement to share costs.","zh-TW":"兩家公司簽署了合資協議以分擔成本。"},{"en":"The joint venture agreement defines each party contribution and profit split.","zh-TW":"合資協議定義了各方的出資和利潤分配。"}]', 'phrasal verb'),
('key metric', '', '', '[{"en":"Revenue growth rate is a key metric for assessing business health.","zh-TW":"收入增長率是評估業務健康的關鍵指標。"},{"en":"Monthly reports highlight key metrics for senior management review.","zh-TW":"月度報告重點展示高級管理層審查的關鍵指標。"}]', 'phrasal verb'),
('land value', '', '', '[{"en":"Rising land values increased the cost of urban development projects.","zh-TW":"上漲的地價增加了城市開發項目的成本。"},{"en":"Land value is a key factor in determining property investment returns.","zh-TW":"地價是決定房地產投資回報的關鍵因素。"}]', 'phrasal verb'),
('launch strategy', '', '', '[{"en":"The launch strategy focused on digital channels and influencer marketing.","zh-TW":"發佈策略聚焦於數位渠道和網紅行銷。"},{"en":"A phased launch strategy reduces risk in unfamiliar markets.","zh-TW":"分階段的上市策略降低了在陌生市場的風險。"}]', 'phrasal verb'),
('lease extension', '', '', '[{"en":"The tenant negotiated a two-year lease extension at favorable terms.","zh-TW":"租客以有利條款談判了兩年的租約延期。"},{"en":"A lease extension avoids the disruption of finding new premises.","zh-TW":"租約延期避免了尋找新場所的麻煩。"}]', 'phrasal verb'),
('legal department', '', '', '[{"en":"All major contracts are reviewed by the legal department.","zh-TW":"所有重大合約都由法律部門審查。"},{"en":"The legal department advises on regulatory compliance and disputes.","zh-TW":"法律部門就監管合規和糾紛提供建議。"}]', 'phrasal verb'),
('limit order', '', '', '[{"en":"He placed a limit order to buy the stock at 50 dollars.","zh-TW":"他下了一個在50元買入股票的限價訂單。"},{"en":"A limit order protects against buying at an unfavorable price.","zh-TW":"限價訂單防止以不利的價格購買。"}]', 'phrasal verb'),
('loan agreement', '', '', '[{"en":"The loan agreement specified a 5-year term at 4% interest.","zh-TW":"貸款協議規定了5年期限以4%利率。"},{"en":"Both parties signed the loan agreement after legal review.","zh-TW":"在法律審查後，雙方簽署了貸款協議。"}]', 'phrasal verb'),
('loss of earnings', '', '', '[{"en":"The storm caused a loss of earnings of 2 million for the business.","zh-TW":"風暴給企業造成了200萬元的收入損失。"},{"en":"The insurance policy covers loss of earnings during business interruption.","zh-TW":"保險政策涵蓋業務中斷期間的收入損失。"}]', 'phrasal verb'),
('management team', '', '', '[{"en":"A strong management team is essential for sustained business growth.","zh-TW":"強大的管理團隊對持續的業務增長至關重要。"},{"en":"The management team presented a turnaround plan to the board.","zh-TW":"管理團隊向董事會提交了扭轉計劃。"}]', 'phrasal verb'),
('market access', '', '', '[{"en":"The trade deal improved market access for foreign companies.","zh-TW":"貿易協議改善了外國公司的市場准入。"},{"en":"Local partners can help provide market access in new regions.","zh-TW":"本地合作夥伴可以幫助在新地區提供市場准入。"}]', 'phrasal verb'),
('material cost', '', '', '[{"en":"Rising material costs were offset by efficiency gains.","zh-TW":"上漲的材料成本被效率提升所抵消。"},{"en":"Material costs represent 40% of the total production cost.","zh-TW":"材料成本占總生產成本的40%。"}]', 'phrasal verb'),
('mid-year review', '', '', '[{"en":"The mid-year review identified the need to reforecast revenue.","zh-TW":"中期審查識別了需要重新預測收入的必要性。"},{"en":"Mid-year reviews allow management to adjust strategies if needed.","zh-TW":"中期審查允許管理層在需要時調整策略。"}]', 'phrasal verb'),
('minority stake', '', '', '[{"en":"The fund acquired a 20% minority stake in the startup.","zh-TW":"基金在新創公司中收購了20%的少數股份。"},{"en":"A minority stake can provide influence without full control.","zh-TW":"少數股份可以在沒有完全控制的情況下提供影響力。"}]', 'phrasal verb'),
('model portfolio', '', '', '[{"en":"The advisor presented a model portfolio aligned to a moderate risk profile.","zh-TW":"顧問展示了符合適中風險偏好的示範投資組合。"},{"en":"Model portfolios simplify investment decisions for retail clients.","zh-TW":"示範投資組合簡化了零售客戶的投資決策。"}]', 'phrasal verb'),
('monthly report', '', '', '[{"en":"All department heads submit monthly reports on the fifth of each month.","zh-TW":"所有部門主管在每月五日提交月度報告。"},{"en":"Monthly reports track progress against annual targets.","zh-TW":"月度報告追蹤年度目標的進展。"}]', 'phrasal verb'),
('net working capital ratio', '', '', '[{"en":"A strong net working capital ratio indicates good short-term solvency.","zh-TW":"強勁的淨營運資金比率表明良好的短期償付能力。"},{"en":"The company improved its net working capital ratio by tightening receivables.","zh-TW":"公司通過收緊應收帳款改善了淨營運資金比率。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('new hire', '', '', '[{"en":"New hires receive a two-week orientation program.","zh-TW":"新進員工接受兩週的入職培訓計劃。"},{"en":"The company welcomed 50 new hires in the first quarter.","zh-TW":"公司在第一季度歡迎了50名新進員工。"}]', 'phrasal verb'),
('new market', '', '', '[{"en":"The company entered three new markets in Southeast Asia.","zh-TW":"公司進入了東南亞三個新市場。"},{"en":"Research is critical before entering a new market.","zh-TW":"在進入新市場前，研究至關重要。"}]', 'phrasal verb'),
('new product development', '', '', '[{"en":"New product development cycles were shortened by 30%.","zh-TW":"新產品開發週期縮短了30%。"},{"en":"New product development is funded by retained earnings.","zh-TW":"新產品開發由留存盈利資助。"}]', 'phrasal verb'),
('nominal value', '', '', '[{"en":"Bonds are issued at nominal value and redeemed at maturity.","zh-TW":"債券按面值發行並在到期時贖回。"},{"en":"The shares have a nominal value of one dollar each.","zh-TW":"股票的名義價值為每股一美元。"}]', 'phrasal verb'),
('non-current assets', '', '', '[{"en":"Property and equipment are classified as non-current assets.","zh-TW":"房產和設備歸類為非流動資產。"},{"en":"Non-current assets are recorded at cost minus accumulated depreciation.","zh-TW":"非流動資產以成本減去累計折舊記錄。"}]', 'phrasal verb'),
('note payable', '', '', '[{"en":"The company issued a note payable to finance the equipment.","zh-TW":"公司發出應付票據為設備融資。"},{"en":"Notes payable are classified under current or non-current liabilities.","zh-TW":"應付票據根據期限歸類為流動或非流動負債。"}]', 'phrasal verb'),
('notice of termination', '', '', '[{"en":"The landlord issued a notice of termination due to unpaid rent.","zh-TW":"房東因未付租金發出了終止通知。"},{"en":"A notice of termination must follow the contractually agreed process.","zh-TW":"終止通知必須遵循合約約定的程序。"}]', 'phrasal verb'),
('offshore banking', '', '', '[{"en":"Multinational companies use offshore banking for treasury operations.","zh-TW":"跨國公司使用離岸銀行業務進行財資運作。"},{"en":"Offshore banking must comply with anti-money laundering regulations.","zh-TW":"離岸銀行業務必須遵守反洗錢法規。"}]', 'phrasal verb'),
('oil price', '', '', '[{"en":"Rising oil prices increased transportation costs for businesses.","zh-TW":"上漲的油價增加了企業的運輸成本。"},{"en":"The company hedged against oil price increases using futures contracts.","zh-TW":"公司使用期貨合約對沖油價上漲風險。"}]', 'phrasal verb'),
('online marketplace', '', '', '[{"en":"The company listed its products on three major online marketplaces.","zh-TW":"公司在三個主要線上交易平台上列出了其產品。"},{"en":"Online marketplace fees eat into seller margins.","zh-TW":"線上交易平台費用侵蝕了賣家的利潤率。"}]', 'phrasal verb'),
('open market', '', '', '[{"en":"The company bought back shares on the open market.","zh-TW":"公司在公開市場上回購了股份。"},{"en":"Open market prices reflect real-time supply and demand.","zh-TW":"公開市場價格反映實時供需狀況。"}]', 'phrasal verb'),
('operating company', '', '', '[{"en":"Each operating company reports results to the holding company.","zh-TW":"每家運營公司向控股公司報告業績。"},{"en":"The operating company was responsible for all customer-facing activities.","zh-TW":"運營公司負責所有面向客戶的活動。"}]', 'phrasal verb'),
('operations manual', '', '', '[{"en":"The new operations manual was distributed to all site managers.","zh-TW":"新的操作手冊已分發給所有現場管理人員。"},{"en":"An operations manual ensures consistency across locations.","zh-TW":"操作手冊確保了各地點的一致性。"}]', 'phrasal verb'),
('order management', '', '', '[{"en":"The order management system reduced processing errors by 40%.","zh-TW":"訂單管理系統將處理錯誤減少了40%。"},{"en":"Effective order management ensures on-time delivery and accurate invoicing.","zh-TW":"有效的訂單管理確保了準時交貨和準確的發票開立。"}]', 'phrasal verb'),
('outbound logistics', '', '', '[{"en":"Improving outbound logistics cut average delivery time by two days.","zh-TW":"改善出貨物流將平均交貨時間縮短了兩天。"},{"en":"Outbound logistics includes warehousing, packing, and shipping.","zh-TW":"出貨物流包括倉儲、包裝和運輸。"}]', 'phrasal verb'),
('out-of-pocket expense', '', '', '[{"en":"Out-of-pocket expenses are reimbursable within the travel policy.","zh-TW":"自付費用在差旅政策範圍內可報銷。"},{"en":"The employee tracked all out-of-pocket expenses on the trip.","zh-TW":"員工追蹤了出差中的所有自付費用。"}]', 'phrasal verb'),
('outsource to a third party', '', '', '[{"en":"The company outsourced payroll to a third party to save time.","zh-TW":"公司將薪資外包給第三方以節省時間。"},{"en":"Outsourcing to a third party can reduce costs but requires strong contracts.","zh-TW":"外包給第三方可以降低成本，但需要強有力的合約。"}]', 'phrasal verb'),
('overdue account', '', '', '[{"en":"All overdue accounts are sent automated payment reminders.","zh-TW":"所有逾期帳戶都會收到自動付款提醒。"},{"en":"The collections team follows up on overdue accounts weekly.","zh-TW":"追收團隊每週跟進逾期帳戶。"}]', 'phrasal verb'),
('overtime pay', '', '', '[{"en":"Employees are entitled to overtime pay at 1.5 times the regular rate.","zh-TW":"員工有權獲得按正常費率1.5倍計算的加班費。"},{"en":"The company limited overtime pay by hiring temporary staff.","zh-TW":"公司通過聘用臨時員工限制了加班費。"}]', 'phrasal verb'),
('own resources', '', '', '[{"en":"The company funded the project using its own resources.","zh-TW":"公司使用自有資源資助了該項目。"},{"en":"Relying on own resources avoids taking on additional debt.","zh-TW":"依靠自有資源避免了承擔額外債務。"}]', 'phrasal verb'),
('owner''s equity', '', '', '[{"en":"A positive owner''s equity means assets exceed liabilities.","zh-TW":"正的業主權益意味著資產超過負債。"},{"en":"Owner''s equity increases when the business retains profits.","zh-TW":"當企業保留利潤時，業主權益增加。"}]', 'phrasal verb'),
('paid leave', '', '', '[{"en":"Employees are entitled to 14 days of paid leave annually.","zh-TW":"員工每年有14天的有薪假期。"},{"en":"Maternity leave is provided as paid leave under company policy.","zh-TW":"育嬰假根據公司政策作為有薪假期提供。"}]', 'phrasal verb'),
('parent guarantee', '', '', '[{"en":"The lender required a parent guarantee before extending credit.","zh-TW":"貸款方在提供信貸前要求了母公司擔保。"},{"en":"A parent guarantee adds security to a subsidiary contract.","zh-TW":"母公司擔保為子公司合約增加了安全保障。"}]', 'phrasal verb'),
('payment terms', '', '', '[{"en":"The standard payment terms are 30 days from invoice date.","zh-TW":"標準付款條款為發票日期後30天。"},{"en":"Negotiating longer payment terms helps manage working capital.","zh-TW":"談判更長的付款條款有助於管理營運資金。"}]', 'phrasal verb'),
('per annum', '', '', '[{"en":"The company has grown at 10% per annum for the last five years.","zh-TW":"公司過去五年每年增長10%。"},{"en":"The bond pays a coupon of 4% per annum.","zh-TW":"債券每年支付4%的票息。"}]', 'phrasal verb'),
('performance target', '', '', '[{"en":"Individual performance targets are aligned with company objectives.","zh-TW":"個人績效目標與公司目標保持一致。"},{"en":"Bonuses are paid when staff achieve their performance targets.","zh-TW":"員工達到績效目標時支付獎金。"}]', 'phrasal verb'),
('pilot test', '', '', '[{"en":"A pilot test was conducted in two stores before the national rollout.","zh-TW":"在全國推廣前在兩家門市進行了試驗。"},{"en":"Pilot test results were used to refine the new system.","zh-TW":"試點測試結果用於完善新系統。"}]', 'phrasal verb'),
('planning cycle', '', '', '[{"en":"The annual planning cycle kicks off in October for the next year.","zh-TW":"年度規劃週期在十月啟動為下一年做準備。"},{"en":"A structured planning cycle improves strategic alignment.","zh-TW":"結構化的規劃週期改善了戰略一致性。"}]', 'phrasal verb'),
('portfolio diversification', '', '', '[{"en":"Portfolio diversification reduces the impact of any single investment loss.","zh-TW":"投資組合多元化降低了任何單一投資損失的影響。"},{"en":"The fund manager pursued portfolio diversification across five asset classes.","zh-TW":"基金管理人在五個資產類別中追求投資組合多元化。"}]', 'phrasal verb'),
('positive working environment', '', '', '[{"en":"A positive working environment reduces absenteeism and improves morale.","zh-TW":"積極的工作環境降低了缺勤率並提升了士氣。"},{"en":"HR initiatives aim to foster a positive working environment for all staff.","zh-TW":"人力資源計劃旨在為所有員工培養積極的工作環境。"}]', 'phrasal verb'),
('price ceiling', '', '', '[{"en":"The government set a price ceiling on essential medicines.","zh-TW":"政府對基本藥物設置了價格上限。"},{"en":"A price ceiling below the market price creates shortages.","zh-TW":"低於市場價格的價格上限造成了短缺。"}]', 'phrasal verb'),
('primary research', '', '', '[{"en":"The team conducted primary research through surveys and interviews.","zh-TW":"團隊通過調查和訪談進行了一手研究。"},{"en":"Primary research provides more targeted data than secondary sources.","zh-TW":"一手研究比二手來源提供更有針對性的數據。"}]', 'phrasal verb'),
('process audit', '', '', '[{"en":"A process audit confirmed the quality management system was effective.","zh-TW":"流程審計確認了品質管理系統的有效性。"},{"en":"The findings of the process audit were shared with all teams.","zh-TW":"流程審計的結果與所有團隊共享了。"}]', 'phrasal verb'),
('procurement manager', '', '', '[{"en":"The procurement manager negotiated a 15% reduction in supplier costs.","zh-TW":"採購經理談判成功將供應商成本降低了15%。"},{"en":"A procurement manager must balance cost, quality, and delivery.","zh-TW":"採購經理必須平衡成本、品質和交貨時間。"}]', 'phrasal verb'),
('production capacity', '', '', '[{"en":"The company doubled its production capacity with the new factory.","zh-TW":"公司通過新工廠將生產能力翻了一倍。"},{"en":"Excess production capacity leads to higher per-unit fixed costs.","zh-TW":"過剩的生產能力導致了更高的單位固定成本。"}]', 'phrasal verb'),
('production cycle', '', '', '[{"en":"Automation reduced the production cycle time from 5 days to 2 days.","zh-TW":"自動化將生產週期從5天縮短到了2天。"},{"en":"A shorter production cycle improves responsiveness to customer orders.","zh-TW":"較短的生產週期改善了對客戶訂單的響應能力。"}]', 'phrasal verb'),
('production schedule', '', '', '[{"en":"The production schedule was adjusted to meet the peak season demand.","zh-TW":"生產計劃調整以滿足旺季需求。"},{"en":"Disruptions in supply forced a revision to the production schedule.","zh-TW":"供應中斷迫使對生產計劃進行了修訂。"}]', 'phrasal verb'),
('profit margin improvement', '', '', '[{"en":"Cost-cutting measures contributed to a profit margin improvement of 3%.","zh-TW":"削減成本措施促成了3%的利潤率改善。"},{"en":"Automation is key to the company''s profit margin improvement plan.","zh-TW":"自動化是公司利潤率改善計劃的關鍵。"}]', 'phrasal verb'),
('profit-sharing plan', '', '', '[{"en":"The profit-sharing plan increased employee motivation significantly.","zh-TW":"利潤分享計劃顯著提高了員工積極性。"},{"en":"Employees received a bonus under the company''s profit-sharing plan.","zh-TW":"員工根據公司的利潤分享計劃收到了獎金。"}]', 'phrasal verb'),
('project brief', '', '', '[{"en":"The project brief was circulated to all stakeholders for approval.","zh-TW":"專案摘要已分發給所有利害關係人以獲取批准。"},{"en":"A detailed project brief prevents misunderstandings later.","zh-TW":"詳細的專案摘要可防止以後產生誤解。"}]', 'phrasal verb'),
('project portfolio', '', '', '[{"en":"The PMO manages a project portfolio of over 20 active initiatives.","zh-TW":"項目管理辦公室管理著超過20個活躍倡議的專案組合。"},{"en":"A balanced project portfolio aligns with strategic business goals.","zh-TW":"均衡的專案組合與戰略業務目標保持一致。"}]', 'phrasal verb'),
('project team', '', '', '[{"en":"The project team met weekly to review progress and resolve issues.","zh-TW":"項目團隊每週開會審查進度並解決問題。"},{"en":"A strong project team is key to delivering on time and on budget.","zh-TW":"強大的項目團隊是按時按預算交付的關鍵。"}]', 'phrasal verb'),
('promotional offer', '', '', '[{"en":"The promotional offer attracted 500 new customers in one week.","zh-TW":"促銷優惠在一週內吸引了500名新客戶。"},{"en":"Promotional offers are typically time-limited to create urgency.","zh-TW":"促銷優惠通常是有時間限制的，以製造緊迫感。"}]', 'phrasal verb'),
('property management', '', '', '[{"en":"A professional property management company handles tenant issues.","zh-TW":"專業的物業管理公司處理租戶問題。"},{"en":"Property management includes maintenance, leasing, and rent collection.","zh-TW":"物業管理包括維護、租賃和收租。"}]', 'phrasal verb'),
('proprietary information', '', '', '[{"en":"Employees must not disclose proprietary information to competitors.","zh-TW":"員工不得向競爭對手披露專有資訊。"},{"en":"The NDA prevents contractors from sharing proprietary information.","zh-TW":"保密協議防止承包商分享專有資訊。"}]', 'phrasal verb'),
('purchase requisition', '', '', '[{"en":"A purchase requisition must be approved before placing an order.","zh-TW":"採購申請單必須在下訂單前獲得批准。"},{"en":"The purchase requisition process ensures budget compliance.","zh-TW":"採購申請單流程確保了預算合規性。"}]', 'phrasal verb'),
('quality assurance program', '', '', '[{"en":"The quality assurance program reduced product defects by 25%.","zh-TW":"品質保證計劃將產品缺陷減少了25%。"},{"en":"All suppliers must comply with the company''s quality assurance program.","zh-TW":"所有供應商必須遵守公司的品質保證計劃。"}]', 'phrasal verb'),
('quality control check', '', '', '[{"en":"Each unit undergoes a quality control check before shipping.","zh-TW":"每個單位在出貨前都要接受品質管制檢查。"},{"en":"The quality control check detected flaws in 2% of units.","zh-TW":"品質管制檢查發現了2%的單位存在缺陷。"}]', 'phrasal verb'),
('rate of exchange', '', '', '[{"en":"The company hedges against rate of exchange fluctuations.","zh-TW":"公司對沖匯率波動風險。"},{"en":"Importers must monitor the rate of exchange daily.","zh-TW":"進口商必須每日監控匯率。"}]', 'phrasal verb'),
('receivables management', '', '', '[{"en":"Effective receivables management reduces the risk of bad debts.","zh-TW":"有效的應收帳款管理降低了壞帳風險。"},{"en":"The finance team implemented a receivables management policy.","zh-TW":"財務團隊實施了應收帳款管理政策。"}]', 'phrasal verb');